INSERT INTO `products` (`id`, `sku`, `vendor_id`, `category_id`, `brand_id`, `title`, `description`, `price`, `original_price`, `discount`, `stock`, `spotlight`, `status`, `rating`, `rating_count`, `created_at`, `updated_at`) VALUES (1,'SKU-FE1E480D',546,2,NULL,'Red T-shirt','Crafted from 100% premium combed cotton (180 GSM), this vibrant Red T-shirt offers ultra-soft comfort and long-lasting durability. Features a classic crew neck, double-stitched reinforced hemline, and breathable bio-washed fabric that resists color fading through numerous washes. Perfect for casual daily wear, workouts, or pairing with denim.',799.00,999.00,0,25,'REGULAR','ACTIVE',4.20,5,'2026-08-13 13:38:13','2026-10-30 17:16:35'),(2,'SKU-0E78DC69',546,2,NULL,'Black T-shirt','An essential wardrobe staple, this Black T-shirt is cut from 100% bio-washed organic cotton for a smooth, irritation-free feel. Features a tailored regular fit, ribbed collar, and deep obsidian black dye that maintains its rich color wash after wash. Highly breathable and moisture-absorbing for all-day comfort.',599.00,799.00,0,25,'REGULAR','ACTIVE',4.50,4,'2026-08-13 13:38:59','2026-10-30 17:16:35'),(3,'SKU-CE32486A',546,2,NULL,'T-shirt and shorts','Premium two-piece summer loungewear and athleisure set featuring a coordinated relaxed-fit cotton tee and matching drawstring fleece shorts. Crafted from breathable lightweight french terry fabric with deep side pockets, flexible elastic waistband, and anti-chafing flatlock stitching. Ideal for gym, running, travel, or relaxed weekends.',999.00,1599.00,0,25,'REGULAR','ACTIVE',4.00,4,'2026-08-13 13:44:53','2026-10-30 17:16:35'),(4,'SKU-0F9E45AF',546,2,NULL,'Blue T-shirt','Showcasing a rich ocean blue hue, this casual crew-neck t-shirt is spun from 100% ringspun combed cotton. Lightweight, breathable, and pre-shrunk to prevent shape distortion. Detailed with taped neck and shoulders for added durability, making it an everyday essential.',599.00,798.99,0,25,'REGULAR','ACTIVE',4.00,4,'2026-08-13 13:45:23','2026-10-30 17:16:35'),(5,'SKU-37F164B6',546,2,NULL,'Navy Blue Polo Tshirt','Elevate your semi-formal style with this Navy Blue Polo T-shirt. Knitted from premium honeycomb pique cotton (220 GSM) offering excellent ventilation. Features a structured ribbed collar, 2-button placket with tonal buttons, and ribbed sleeve cuffs. Retains shape and structure effortlessly.',999.00,1499.00,0,25,'BESTSELLER','ACTIVE',4.50,4,'2026-08-13 13:45:46','2026-10-30 17:16:35'),(6,'SKU-00C82882',546,2,NULL,'Brown Polo T-shirt','A sophisticated earthy addition to any wardrobe, this Mocha Brown Polo T-shirt blends cotton-rich pique fabric with a touch of stretch for ultimate ease of movement. Styled with a crisp flat-knit collar, reinforced side vents, and clean contrast buttons.',799.00,1499.00,0,25,'REGULAR','ACTIVE',4.67,6,'2026-08-13 13:46:15','2026-10-30 17:16:35'),(7,'SKU-019E8939',546,2,NULL,'Green Tshirt','Refresh your look with this Forest Green cotton crewneck t-shirt. Manufactured from 100% sustainably sourced bio-wash cotton. Features a relaxed comfort fit, ribbed crewneck, and sweat-wicking properties to keep you cool and dry throughout warm weather.',599.00,1499.00,0,25,'REGULAR','ACTIVE',4.00,4,'2026-08-13 13:46:39','2026-10-30 17:16:35'),(8,'SKU-B461E470',546,2,NULL,'Blue baggy Jeans','Authentic 90s retro skater-inspired Blue Baggy Jeans engineered from 100% heavy-duty 13.5 oz cotton denim. Designed with a mid-rise waist, wide leg profile from hip to hem, brass rivets at stress points, and genuine YKK zipper fly. Effortlessly pairs with oversized tees and sneakers.',999.00,1499.00,0,25,'BESTSELLER','ACTIVE',4.67,6,'2026-08-13 13:52:48','2026-10-30 17:16:35'),(9,'SKU-EF7D6BF7',546,2,NULL,'Beige jacket & Blue baggy jeans combo','Curated streetwear outfit combo consisting of a durable Beige Canvas Twill Utility Overshirt Jacket paired with Classic Blue Wide-Leg Baggy Jeans. The jacket features chest flap pockets and horn buttons, while the jeans feature heavy-gauge denim with a relaxed skater silhouette.',2999.00,2599.00,0,25,'REGULAR','ACTIVE',4.00,5,'2026-08-13 13:55:13','2026-10-30 17:16:35'),(10,'SKU-8788E917',546,2,NULL,'Blue Baggy jeans','Vintage light-wash blue baggy denim featuring relaxed street-style drape. Reinforced with five traditional pockets, durable belt loops, and copper rivet accents. Premium washed cotton denim softens with every wear while retaining structural durability.',799.00,999.00,0,25,'REGULAR','ACTIVE',4.75,4,'2026-08-13 13:57:03','2026-10-30 17:16:35'),(11,'SKU-BF5617B7',546,2,NULL,'Vintage Baggy jeans','Distressed acid-wash retro baggy jeans with a loose-fitting silhouette. Cut from heavyweight pure cotton denim with authentic vintage fading, high-rise waist, roomy thigh room, and reinforced double-needle seam stitching.',999.00,1499.00,0,25,'BESTSELLER','ACTIVE',4.00,5,'2026-08-13 13:58:09','2026-10-30 17:16:35'),(12,'SKU-C4544E9F',547,1,NULL,'IPhone 17 pro max','Apple iPhone 17 Pro Max featuring an aerospace-grade Grade 5 titanium chassis and cutting-edge A19 Pro 2nm Bionic Chip. Boasts a massive 6.9-inch Super Retina XDR OLED display with 1-120Hz ProMotion, 48MP Fusion Triple Camera system with 5x optical telephoto, Action Button, Ceramic Shield 2.0, USB-C 3.2 data transfer, and all-day 33-hour video playback battery life.',129000.00,149000.00,0,25,'BESTSELLER','ACTIVE',5.00,4,'2026-08-13 14:11:19','2026-10-30 17:16:35'),(13,'SKU-3091F7B1',547,1,NULL,'IPhone 17','Apple iPhone 17 powered by the groundbreaking A19 Bionic chip and next-generation Neural Engine. Features a vibrant 6.3-inch Super Retina XDR OLED display, advanced dual-camera system with 48MP main sensor, 4K Dolby Vision cinematic video, Dynamic Island, and USB-C charging.',78999.00,80599.00,0,25,'BESTSELLER','ACTIVE',4.80,5,'2026-08-13 14:12:16','2026-10-30 17:16:35'),(14,'SKU-52A2C505',547,1,NULL,'Play Station 5','Sony PlayStation 5 Console featuring custom ultra-high-speed 825GB NVMe SSD, AMD Ryzen Zen 2 CPU, and custom RDNA 2 GPU supporting Hardware Ray Tracing, 4K 120Hz output, and Tempest 3D AudioTech. Includes DualSense Wireless Controller with adaptive triggers and haptic feedback.',49999.00,54999.00,0,25,'REGULAR','ACTIVE',4.50,4,'2026-08-13 14:13:00','2026-10-30 17:16:35'),(15,'SKU-ECB055B4',547,1,NULL,'IPhone Air','The thinnest, most refined iPhone ever created: Apple iPhone Air. Ultra-sleek 5.5mm aerospace titanium unibody, 6.6-inch ProMotion 120Hz OLED, A19 Bionic architecture, eSIM exclusive, advanced spatial photography, and lightning-fast MagSafe fast charging.',109999.00,119999.00,0,24,'REGULAR','ACTIVE',4.67,6,'2026-08-13 14:14:23','2026-10-30 17:16:35'),(16,'SKU-9C30D8BE',547,1,NULL,'IPhone 16','Apple iPhone 16 engineered for Apple Intelligence. Packed with the A18 processor, dedicated Camera Control tactile button, 48MP Fusion camera with 2x in-sensor optical zoom, macro capabilities, Dynamic Island, and aerospace-grade aluminum chassis with color-infused back glass.',69999.00,79999.00,0,23,'REGULAR','ACTIVE',4.60,5,'2026-08-13 14:15:43','2026-10-30 17:16:35'),(17,'SKU-62415D73',547,1,NULL,'Apple Airpods Pro 3','Apple AirPods Pro (3rd Generation) delivering studio-grade Active Noise Cancellation (2x more effective), Adaptive Audio, Personalized Spatial Audio with dynamic head tracking, heart-rate sensing, and USB-C MagSafe charging case with Precision Finding speaker.',23599.00,25900.00,0,25,'FEATURED','ACTIVE',4.17,6,'2026-08-13 14:29:49','2026-10-30 17:16:35'),(18,'SKU-A5E72843',547,1,NULL,'Airpods Max 2','Apple AirPods Max 2 premium over-ear headphones. Engineered with Apple-designed dynamic drivers, computational audio via H2 chip, Pro-level Active Noise Cancellation, Transparency mode, breathable knit mesh canopy, anodized aluminum earcups, and USB-C lossless audio playback.',66998.00,67900.00,0,25,'REGULAR','ACTIVE',4.00,5,'2026-08-13 14:30:51','2026-10-30 17:16:35'),(19,'SKU-E77712DF',547,1,NULL,'Samsung S26 Ultra','Samsung Galaxy S26 Ultra 5G featuring integrated Bluetooth S-Pen, 6.8-inch Dynamic AMOLED 2X QHD+ 120Hz display with anti-reflective Gorilla Armor. Powered by Qualcomm Snapdragon 8 Gen 5 for Galaxy, 200MP ISOCELL quad-camera with 100x Space Zoom, Galaxy AI suite, and 5000mAh battery with 45W fast charge.',129999.00,139999.00,0,23,'REGULAR','ACTIVE',4.75,4,'2026-08-13 14:32:01','2026-10-30 17:16:35'),(20,'SKU-7DFBC7B6',547,1,NULL,'Macbook M5','Apple MacBook Pro powered by the revolutionary Apple M5 chip (12-core CPU, 18-core GPU, 16-core Neural Engine). Features a breathtaking 16.2-inch Liquid Retina XDR display with 1600 nits peak HDR brightness, 36GB unified memory, 1TB high-speed SSD, studio-grade three-mic array, six-speaker sound system with force-cancelling woofers, and up to 24-hour battery endurance.',199999.00,249999.00,0,24,'REGULAR','ACTIVE',4.33,6,'2026-08-13 14:34:09','2026-10-30 17:16:35'),(21,'SKU-F35A0A4E',548,1,NULL,'iPhone 18 Pro','## Apple iPhone 18 Pro\r\n\r\nExperience next-generation performance and professional-level photography with the **iPhone 18 Pro**. Designed with a premium Pro build, an advanced camera system, and powerful Apple silicon, it delivers a smooth and immersive experience for everyday use, gaming, photography, video creation, and productivity.\r\n\r\n### Key Highlights\r\n\r\n* **Premium Pro Design** — Elegant, durable construction with a refined flagship look.\r\n* **Advanced Pro Display** — Bright, smooth and immersive display designed for entertainment and creative work.\r\n* **Next-Generation Pro Chip** — Powerful performance for demanding apps, gaming, editing and multitasking.\r\n* **Pro Camera System** — Capture detailed photos and cinematic-quality video with advanced imaging capabilities.\r\n* **All-Day Battery** — Built for long hours of streaming, photography, communication and productivity.\r\n* **iOS Experience** — Secure, intuitive software with regular updates and seamless integration across Apple devices.\r\n* **5G Connectivity** — Fast downl